 *         line: 5,
 *     );
 *     $statement->hasAssertion() // => true
 *
 * @example Statement without assertion (smoke test)
 *     $statement = new \Doctest\Assertion\Statement(
 *         code: '$x = 1;',
 *         assertion: null,
 *         line: 10,
 *     );
