     * Returns the documented declarations of the given statements.
     *
     * @param array<mixed> $statements
     * @return list<Target>
     */
    public function declarations(array $statements, string $path, string $namespace, ?string $className): array
    {
        $targets = [];
        foreach ($statements as $statement) {
            if ($statement instanceof \PhpParser\Node\Stmt\Namespace_) {
                $inner = $statement->name === null ? '' : $statement->name->toString();
                $targets = array_merge($targets, $this->declarations($statement->stmts, $path, $inner, null));
