            if ($statement instanceof \PhpParser\Node\Stmt\Function_) {
                $target = $this->target(Target::FUNCTION, $statement, $path, $statement->name->toString(), $namespace, null);
                $targets = array_merge($targets, $target === null ? [] : [$target]);
                continue;
