        $name = $node->name->toString();
        $target = $this->target(Target::CLASS_LIKE, $node, $path, $name, $namespace, null);
        $targets = $target === null ? [] : [$target];

        return array_merge($targets, $this->declarations($node->stmts, $path, $namespace, $name));
    }

    /**
     * Returns the documented declarations nested inside a control-flow statement.
     *
     * @return list<Target>
     */
    public function nestedDeclarations(\PhpParser\Node $statement, string $path, string $namespace, ?string $className): array
    {
        $nested = [];
        foreach ($statement->getSubNodeNames() as $subNodeName) {
            $value = $statement->{$subNodeName} ?? null;
            if (is_array($value)) {
                $nested = array_merge($nested, $this->declarations($value, $path, $namespace, $className));
            }
        }

        return $nested;
    }

    /**
     * Builds a target for a documented node, or returns null when it has no docblock.
     */
    public function target(string $kind, \PhpParser\Node $node, string $path, string $name, string $namespace, ?string $className): ?Target
    {
        $docComment = $node->getDocComment();
        if ($docComment === null) {
            return null;
        }

        return new Target($kind, $path, $docComment->getText(), $name, $docComment->getStartLine(), $namespace, $className);
