final class ExampleTest extends TestCase
{
    public static function methodTarget(): Target
    {
        return new Target(Target::METHOD, '/app/src/Ledger.php', '/** */', 'append', 10, 'App', 'Ledger');
    }

    public function testIdCombinesTheSymbolWithTheOneBasedExampleNumber(): void
    {
        $example = new Example(self::methodTarget(), new DocExample(null, 'append()', 'tag', 1), 14);

        self::assertSame('App\Ledger::append()#2', $example->id());
    }

    public function testNameReadsAsAHeadingWithTheDescription(): void
    {
        $described = new Example(self::methodTarget(), new DocExample('Appending an entry', 'append()', 'tag', 0), 14);
        $plain = new Example(self::methodTarget(), new DocExample(null, 'append()', 'tag', 0), 14);

        self::assertSame('Ledger::append() example #1: Appending an entry', $described->name());
        self::assertSame('Ledger::append() example #1', $plain->name());
    }

    public function testCodeReturnsTheExampleBody(): void
    {
        self::assertSame('append()', (new Example(self::methodTarget(), new DocExample(null, 'append()', 'tag', 0), 14))->code());
    }

