        self::assertFalse($loader->isDefined(new Target(Target::FUNCTION, '/a.php', '/** */', 'missingFunction', 1, $namespace)));
        self::assertTrue($loader->isDefined(new Target(Target::FUNCTION, '/a.php', '/** */', 'strlen', 1)));
