/**
 * Configuration module for doctest.
 *
 * @example File-level example: creating config with defaults
 *     $config = new \PhpAiToolkit\Doctest\Configuration\Configuration();
 *     $config->isEnabled() // => true
 *     $config->getDirectories() // => []
