<?php

declare(strict_types=1);

namespace PhpAiToolkit\Doctest\TestCase;

use Override;
use PhpAiToolkit\Doctest\Executor\ExampleExecutor;
use PhpAiToolkit\Doctest\Parser\Example;
use PHPUnit\Framework\TestCase;

/**
 * PHPUnit test case for a single doctest example.
 *
 * DoctestCase wraps an Example and executes it as a PHPUnit test. It is the
 * entry point for assembling a suite of examples by hand, where DoctestRunner
 * builds one from a Configuration.
 *
 * An adaptation the port needs: k-kinzal/doctest-php passes the example name to
 * the PHPUnit constructor as the test name, which PHPUnit 9 allowed and PHPUnit
 * 10 no longer does — the constructor argument has to name a real method there.
 * The case therefore names its own runDoctestExample() method and reports the
 * example name through toString(), which is what PHPUnit prints either way.
 */
final class DoctestCase extends TestCase
{
    /** @readonly */
    private ExampleExecutor $executor;

    /**
     * @param Example $example the example to test
     * @param string|null $bootstrap path to a bootstrap file
     */
    public function __construct(
        /** @readonly */
        private Example $example,
        ?string $bootstrap = null,
    ) {
        parent::__construct('runDoctestExample');

        $this->executor = new ExampleExecutor($bootstrap);
    }

    /**
     * Returns a string representation of the test.
     */
    #[Override]
    public function toString(): string
    {
        return $this->example->getTestName();
    }

    /**
     * Runs the doctest example.
     *
     * The name is not test-prefixed on purpose: a DoctestCase is constructed
     * for one example and added to a suite, never discovered by PHPUnit.
     */
    public function runDoctestExample(): void
    {
        $result = $this->executor->execute($this->example);

        self::assertTrue($result->passed, $result->getErrorMessage());
    }
}
